const b = $input.first().json;
const errors = [];
const isUuid = (s) => typeof s === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(s);
const allowedKeys = new Set(['channel_id','content_project_id','idempotency_key','correlation_id','_dev_fail_after_step']);
for (const k of Object.keys(b)) { if (!allowedKeys.has(k)) errors.push(`unknown field: ${k}`); }
if (!isUuid(b.channel_id)) errors.push('channel_id must be a UUID');
if (!isUuid(b.content_project_id)) errors.push('content_project_id must be a UUID');
if (typeof b.idempotency_key !== 'string' || b.idempotency_key.length === 0 || b.idempotency_key.length > 500) errors.push('idempotency_key must be a non-empty string up to 500 characters');
if (b.correlation_id != null && !isUuid(b.correlation_id)) errors.push('correlation_id must be a UUID');
return [{ json: {
  valid: errors.length === 0, errors,
  channel_id: b.channel_id, content_project_id: b.content_project_id,
  idempotency_key: b.idempotency_key ?? null, correlation_id: b.correlation_id ?? null,
  _dev_fail_after_step: b._dev_fail_after_step ?? null
} }];

const v = $input.first().json;
return [{ json: {
  success: false, data: null,
  error: { code: 'INVALID_EXECUTION_CONTEXT', message: 'request failed validation: ' + v.errors.join('; '), retryable: false, error_id: null },
  runtime: { channel_id: null, workflow_run_id: null, content_project_id: null, correlation_id: v.correlation_id ?? null }
} }];

