const stepsArr = $input.first().json.steps || [];
const byName = {};
for (const s of stepsArr) byName[s.step_name] = s;
const flag = (n) => byName[n]?.status === 'succeeded';
const out = (n) => byName[n]?.output ?? null;
return [{ json: {
